class TTLCache:
    def __init__(self, now=None):
        self._now = now or time.monotonic
        self._values = {}
        self._inflight = {}
        self._lock = threading.Lock()

    def get_or_set(self, key, loader, ttl, stale_if_error=False):
        with self._lock:
            entry = self._values.get(key)
            now = self._now()
            if entry is not None and entry["expires_at"] > now:
                return entry["value"]

            inflight = self._inflight.get(key)
            if inflight is None:
                inflight = _InflightLoad()
                self._inflight[key] = inflight
                should_load = True
            else:
                should_load = False

        if not should_load:
            inflight.event.wait()
            if inflight.exception is None:
                return inflight.value

            if stale_if_error:
                with self._lock:
                    entry = self._values.get(key)
                    if entry is not None:
                        return entry["value"]

            raise inflight.exception

        try:
            value = loader()
        except Exception as exc:
            inflight.exception = exc
            with self._lock:
                entry = self._values.get(key)
                inflight.event.set()
                self._inflight.pop(key, None)
            if stale_if_error and entry is not None:
                return entry["value"]
            raise

        expires_at = self._now() + ttl
        inflight.value = value
        with self._lock:
            self._values[key] = {"value": value, "expires_at": expires_at}
            inflight.event.set()
            self._inflight.pop(key, None)
        return value

    def clear(self):
        with self._lock:
            self._values.clear()
